style.css:
/* soft beige background */
body {
  background-color: #f6f1ec !important;
}

/* panels / header */
div[class*="bar"],
div[class*="header"],
div[class*="panel"] {
  background-color: #ead8dc !important;
  border-radius: 18px !important;
}

/* cards */
div[class*="card"],
div[role="button"] {
  background-color: #ffffff !important;
  border-radius: 22px !important;
  box-shadow: 0 6px 18px rgba(140, 120, 125, 0.12) !important;
}

/* buttons */
button {
  background-color: #e6cfd3 !important;
  color: #4f4448 !important;
  border-radius: 20px !important;
  border: none !important;
}

button:hover {
  background-color: #dcbec3 !important;
}

/* text */
h1, h2, h3 {
  font-family: "Playfair Display", serif !important;
  color: #4a4044 !important;
}

p, span, div {
  color: #6b5f63 !important;
}

/* scrollbar */
::-webkit-scrollbar-thumb {
  background: #dcbec3;
  border-radius: 10px;
}
